618: function drawEnemy(enemy) {
619:   if (!enemy.alive && enemy.squishTimer <= 0) return;
620:   const x = enemy.x - cameraX;
621:   const squishProgress = enemy.alive ? 0 : 1 - enemy.squishTimer / ENEMY_SQUISH_DURATION;
622:   const squashIn = clamp(squishProgress / 0.16, 0, 1);
623:   const squeeze = 1 - Math.pow(1 - squashIn, 3);
624:   const scaleY = 1 - squeeze * 0.68;
625:   const scaleX = 1 + squeeze * 0.38;
626:   const fade = enemy.alive ? 1 : clamp(enemy.squishTimer / (ENEMY_SQUISH_DURATION * 0.42), 0, 1);
627:   const bounce = enemy.alive ? Math.sin(elapsed * 8 + enemy.x * 0.2) * 1.5 : 0;
628:   const anchorY = enemy.y + enemy.h;
629: 
630:   ctx.save();
631:   ctx.globalAlpha *= fade;
632:   ctx.translate(x + enemy.w / 2, anchorY);
633:   ctx.scale(scaleX, scaleY);
634:   ctx.translate(-(x + enemy.w / 2), -anchorY);
635: 
636:   ctx.fillStyle = 'rgba(58,38,28,0.2)';
637:   ctx.beginPath();
638:   ctx.ellipse(x + enemy.w / 2, GROUND_Y - 1, 18, 4, 0, 0, Math.PI * 2);
639:   ctx.fill();
640: 
641:   const body = ctx.createRadialGradient(x + 12, enemy.y + 8 + bounce, 2, x + 17, enemy.y + 17 + bounce, 20);
642:   body.addColorStop(0, '#e7ac64');
643:   body.addColorStop(0.65, '#b77b3f');
644:   body.addColorStop(1, '#704322');
645:   ctx.fillStyle = body;
646:   ctx.beginPath();
647:   ctx.ellipse(x + enemy.w / 2, enemy.y + 19 + bounce, 18, 11, 0, 0, Math.PI * 2);
648:   ctx.fill();
649: 
650:   const cap = ctx.createLinearGradient(0, enemy.y + bounce, 0, enemy.y + 17 + bounce);
651:   cap.addColorStop(0, '#f0bd77');
652:   cap.addColorStop(0.55, '#c78a4c');
653:   cap.addColorStop(1, '#8a552e');
654:   ctx.fillStyle = cap;
655:   ctx.beginPath();
656:   ctx.arc(x + enemy.w / 2, enemy.y + 14 + bounce, 15, Math.PI, 0);
657:   ctx.fill();
658:   ctx.fillStyle = 'rgba(255,235,190,0.5)';
659:   ctx.beginPath();
660:   ctx.ellipse(x + 12, enemy.y + 6 + bounce, 5, 2, -0.25, 0, Math.PI * 2);
661:   ctx.fill();
662: 
663:   if (enemy.alive) {
664:     ctx.fillStyle = '#fff7df';
665:     ctx.fillRect(x + 9, enemy.y + 12 + bounce, 6, 8);
666:     ctx.fillRect(x + 21, enemy.y + 12 + bounce, 6, 8);
667:     ctx.fillStyle = '#30241d';
668:     ctx.fillRect(x + 12, enemy.y + 15 + bounce, 3, 4);
669:     ctx.fillRect(x + 22, enemy.y + 15 + bounce, 3, 4);
670:     ctx.fillStyle = '#fff';
671:     ctx.fillRect(x + 12, enemy.y + 15 + bounce, 1, 1);
672:     ctx.fillRect(x + 22, enemy.y + 15 + bounce, 1, 1);
673:   } else {
674:     ctx.strokeStyle = '#4b3023';
675:     ctx.lineWidth = 2;
676:     ctx.lineCap = 'round';
677:     ctx.beginPath();
678:     ctx.moveTo(x + 10, enemy.y + 17 + bounce);
679:     ctx.lineTo(x + 15, enemy.y + 16 + bounce);
680:     ctx.moveTo(x + 21, enemy.y + 16 + bounce);
681:     ctx.lineTo(x + 26, enemy.y + 17 + bounce);
682:     ctx.stroke();
683:     ctx.strokeStyle = '#704322';
684:     ctx.lineWidth = 1.5;
685:     ctx.beginPath();
686:     ctx.moveTo(x + 15, enemy.y + 22 + bounce);
687:     ctx.quadraticCurveTo(x + 18, enemy.y + 24 + bounce, x + 21, enemy.y + 22 + bounce);
688:     ctx.stroke();
689:   }
690: 
691:   roundedGradientRect(x + 3, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
692:   roundedGradientRect(x + 21, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
693:   ctx.restore();
694: }
