696: function drawPlayer() {
697:   if (!player) return;
698:   if (player.invulnerable > 0 && Math.floor(elapsed * 15) % 2) return;
699: 
700:   const x = Math.round(player.x - cameraX);
701:   const y = Math.round(player.y);
702:   const speed = Math.abs(player.vx);
703:   const moving = player.grounded && speed > 18;
704:   const runAmount = moving ? clamp(speed / 150, 0, 1) : 0;
705:   const phase = player.walk;
706:   const stride = moving ? Math.sin(phase) : 0;
707:   const duck = player.duckBlend || 0;
708:   const bob = moving ? Math.abs(Math.sin(phase)) * 1.8 * runAmount * (1 - duck) : Math.sin(elapsed * 10) * 0.45 * duck;
709:   const lean = moving ? clamp(player.vx / 285, -1, 1) * 0.12 * (1 - duck) : 0;
710:   const airborne = !player.grounded;
711:   const shadowY = Math.max(0, GROUND_Y - (y + player.h));
712: 
713:   ctx.fillStyle = `rgba(46,37,32,${Math.max(0.08, 0.2 - shadowY * 0.0007)})`;
714:   ctx.beginPath();
715:   ctx.ellipse(x + player.w / 2, y + player.h + 2, Math.max(7, 13 - shadowY * 0.06), 4, 0, 0, Math.PI * 2);
716:   ctx.fill();
717: 
718:   ctx.save();
719:   ctx.translate(x + player.w / 2, y + player.h / 2 + bob + duck * 6);
720:   ctx.scale(player.facing, 1);
721:   ctx.scale(1, (1 + (moving ? Math.sin(phase * 2) * 0.025 * runAmount : 0)) * (1 - duck * 0.34));
722:   ctx.rotate(airborne ? (player.vy < 0 ? -0.08 : 0.07) * (1 - duck) : -lean);
723: 
724:   // Arms counter-swing on a run, then tuck in as the player settles into a crouch.
725:   const armSwing = moving ? stride * 0.88 * runAmount : airborne ? -0.4 : 0.08;
726:   const crouchedArm = armSwing * (1 - duck) + duck * 0.82;
727:   const drawLimb = (px, py, angle, length, width, top, bottom) => {
728:     ctx.save();
729:     ctx.translate(px, py);
730:     ctx.rotate(angle);
731:     roundedGradientRect(-width / 2, 0, width, length, width / 2, top, bottom);
732:     ctx.restore();
733:   };
734:   const drawShoe = (px, py, angle, length, width, top, bottom) => {
735:     ctx.save();
736:     ctx.translate(px, py);
737:     ctx.rotate(angle);
738:     ctx.fillStyle = bottom;
739:     ctx.beginPath();
740:     ctx.moveTo(-width * 0.55, width * 0.18);
741:     ctx.lineTo(length * 0.72, width * 0.2);
742:     ctx.quadraticCurveTo(length, width * 0.2, length * 0.88, width * 0.62);
743:     ctx.lineTo(-width * 0.52, width * 0.62);
744:     ctx.quadraticCurveTo(-width * 0.82, width * 0.46, -width * 0.55, width * 0.18);
745:     ctx.fill();
746:     ctx.fillStyle = top;
747:     ctx.beginPath();
748:     ctx.moveTo(-width * 0.62, -width * 0.28);
749:     ctx.lineTo(length * 0.58, -width * 0.48);
750:     ctx.quadraticCurveTo(length, -width * 0.42, length * 0.94, 0);
751:     ctx.lineTo(length * 0.76, width * 0.24);
752:     ctx.lineTo(-width * 0.46, width * 0.18);
753:     ctx.quadraticCurveTo(-width * 0.8, 0, -width * 0.62, -width * 0.28);
754:     ctx.fill();
755:     ctx.restore();
756:   };
757: 
758:   // Legs swing in a wide side-profile arc: one reaches forward as the other pushes back.
759:   const legSwing = moving ? Math.sin(phase) * 1.25 * runAmount : 0;
760:   const backLeg = airborne ? 0.9 : legSwing + duck * 0.9;
761:   const frontLeg = airborne ? -0.65 : -legSwing - duck * 0.9;
762:   const farLegX = -2.5 - Math.sin(phase) * 1.6 * runAmount;
763:   const nearLegX = 2.5 + Math.sin(phase) * 1.6 * runAmount;
764:   const farFootX = farLegX - Math.sin(backLeg) * 10;
765:   const farFootY = 15 + Math.cos(backLeg) * 10;
766:   const nearFootX = nearLegX - Math.sin(frontLeg) * 10;
767:   const nearFootY = 14 + Math.cos(frontLeg) * 10;
768:   drawLimb(farLegX, 13, backLeg, 10, 5, '#3983dd', '#164c9d');
769:   drawShoe(farFootX, farFootY, backLeg * 0.16, 11, 5.5, '#d58d57', '#6f3b2d');
770: 
771:   // Back arm, torso, and the forward arm are separate layers for a little depth.
772:   drawLimb(-7, -4, crouchedArm, 12 - duck * 2, 5, '#f2bd91', '#bd7958');
773:   roundedGradientRect(-9, -4, 17, 19, 5, '#5fb0ff', '#174d9d');
774:   // Bring the front leg over the shirt so its forward/back swing stays readable.
775:   drawLimb(nearLegX, 12, frontLeg, 10.5, 5.5, '#55a5ff', '#1553b5');
776:   drawShoe(nearFootX, nearFootY, frontLeg * 0.16, 11, 6, '#bd6c45', '#4f2a20');
777:   ctx.fillStyle = 'rgba(215,237,255,0.58)';
778:   ctx.beginPath();
779:   ctx.moveTo(-5, -1);
780:   ctx.lineTo(-2, -2);
781:   ctx.lineTo(-2, 11);
782:   ctx.lineTo(-5, 12);
783:   ctx.closePath();
784:   ctx.fill();
785:   roundedGradientRect(0, 8, 7, 7, 2, '#f8cc4f', '#ca7b21');
786:   ctx.fillStyle = 'rgba(255,238,172,0.8)';
787:   ctx.fillRect(1, 9, 2, 3);
788:   drawLimb(6, -3, -crouchedArm * 0.85, 11 - duck * 2, 6, '#ffd2a8', '#c17b58');
789: 
790:   // Profiled face: a single eye, a small forward nose, and a visible ear.
791:   const face = ctx.createLinearGradient(-7, -16, 10, 3);
792:   face.addColorStop(0, '#ffe8c2');
793:   face.addColorStop(0.68, '#f2bd8c');
794:   face.addColorStop(1, '#ce875d');
795:   ctx.fillStyle = face;
796:   ctx.beginPath();
797:   ctx.moveTo(-8, -15);
798:   ctx.quadraticCurveTo(-2, -19, 5, -15);
799:   ctx.quadraticCurveTo(9, -13, 8, -9);
800:   ctx.lineTo(12, -6);
801:   ctx.quadraticCurveTo(13, -4, 9, -3);
802:   ctx.lineTo(8, 1);
803:   ctx.quadraticCurveTo(3, 5, -5, 2);
804:   ctx.quadraticCurveTo(-10, -2, -8, -15);
805:   ctx.fill();
806: 
807:   ctx.fillStyle = '#d58c60';
808:   ctx.beginPath();
809:   ctx.ellipse(-5, -5, 2.5, 3, 0, 0, Math.PI * 2);
810:   ctx.fill();
811:   ctx.fillStyle = '#fffdf4';
812:   ctx.beginPath();
813:   ctx.ellipse(4, -10, 2.3, 3.2, -0.12, 0, Math.PI * 2);
814:   ctx.fill();
815:   ctx.fillStyle = '#30252a';
816:   ctx.beginPath();
817:   ctx.ellipse(5.2, -9.5, 1.1, 2.2, 0, 0, Math.PI * 2);
818:   ctx.fill();
819:   ctx.fillStyle = 'rgba(255,255,255,0.9)';
820:   ctx.fillRect(5, -11, 1, 1);
821:   ctx.fillStyle = '#8b423b';
